import { cache } from "react";
import { auth } from "@clerk/nextjs/server";
import { prisma } from "./db";
import type { GlobalRole } from "@/generated/prisma/client";

export interface CurrentUser {
  id: string;
  email: string;
  name: string | null;
  image: string | null;
  globalRole: GlobalRole;
  personId: string | null;
}

/**
 * Get the current authenticated user from Clerk.
 * Returns null if not authenticated.
 *
 * Wrapped with React.cache so multiple calls within the same request
 * share a single DB query (layout + page both calling this = 1 query).
 */
export const getCurrentUser = cache(async (): Promise<CurrentUser | null> => {
  // Check for Clerk session
  const { userId: clerkUserId } = await auth();
  if (!clerkUserId) {
    return null;
  }

  // Fetch user from database
  const user = await prisma.user.findUnique({
    where: { clerkUserId },
  });

  if (!user || user.isDeprovisioned) {
    return null;
  }

  return {
    id: user.id,
    email: user.email,
    name: user.name,
    image: user.image,
    globalRole: user.globalRole,
    personId: user.personId,
  };
});

/**
 * Get customer IDs assigned to a user (via their personId).
 * Returns all customer IDs if user is admin/manager, or assigned customer IDs if regular user.
 *
 * Wrapped with React.cache so multiple calls within the same request share a single DB query.
 */
export const getUserAssignedCustomerIds = cache(async (
  user: CurrentUser
): Promise<string[] | "all"> => {
  if (user.globalRole === "ADMIN" || user.globalRole === "MANAGER") {
    return "all";
  }

  if (!user.personId) {
    return [];
  }

  const assignments = await prisma.customerAssignment.findMany({
    where: { personId: user.personId },
    select: { customerId: true },
  });

  return assignments.map((a) => a.customerId);
});

