import { PgBoss } from "pg-boss";
import { logger } from "@/lib/logger";

const globalForBoss = globalThis as unknown as {
  boss: PgBoss | null | undefined;
};

export async function getBoss(): Promise<PgBoss> {
  if (!globalForBoss.boss) {
    const databaseUrl = process.env.DATABASE_URL;
    if (!databaseUrl) {
      throw new Error("DATABASE_URL environment variable is not set");
    }

    const instance = new PgBoss(databaseUrl);
    globalForBoss.boss = instance;
    try {
      await instance.start();
    } catch (error) {
      globalForBoss.boss = null;
      throw new Error("Failed to start pg-boss instance", { cause: error });
    }
    logger.log("pg-boss started successfully");
  } else {
    logger.log("pg-boss already initialized; reusing existing instance");
  }
  const boss = globalForBoss.boss;
  if (!boss) {
    throw new Error("pg-boss is not initialized");
  }
  return boss;
}

export async function closeBoss(options?: { timeout?: number }): Promise<void> {
  if (globalForBoss.boss) {
    await globalForBoss.boss.stop({ timeout: options?.timeout ?? 5000 });
    globalForBoss.boss = null;
    logger.log("pg-boss stopped");
  }
}

