1	import { NextRequest, NextResponse } from "next/server";
2	import { prisma } from "@/lib/db";
3	import { getCurrentUser } from "@/lib/get-current-user";
4	import { logger } from "@/lib/logger";
5	
6	export async function POST(
7	  _req: NextRequest,
8	  { params }: { params: Promise<{ jobId: string }> }
9	) {
10	  try {
11	    // Check authentication
12	    const user = await getCurrentUser();
13	    if (!user) {
14	      return NextResponse.json(
15	        { error: "Unauthorized" },
16	        { status: 401 }
17	      );
18	    }
19	
20	    const { jobId } = await params;
21	
22	    // Check the job exists and verify authorization
23	    const existingJob = await prisma.syncJob.findUnique({
24	      where: { id: jobId },
25	      select: { createdById: true },
26	    });
27	
28	    if (!existingJob) {
29	      return NextResponse.json(
30	        { error: "Job not found" },
31	        { status: 404 }
32	      );
33	    }
34	
35	    // Admins can cancel all jobs; other users can only cancel jobs they created
36	    if (user.globalRole !== "ADMIN" && existingJob.createdById !== user.id) {
37	      return NextResponse.json(
38	        { error: "Forbidden: Admin role required" },
39	        { status: 403 }
40	      );
41	    }
42	
43	    // Update the job status to CANCELLED, selecting only client-safe fields
44	    const job = await prisma.syncJob.update({
