import { NextRequest, NextResponse } from "next/server";
import { prisma } from "@/lib/db";
import { getCurrentUser } from "@/lib/get-current-user";
import { logger } from "@/lib/logger";

export async function POST(
  _req: NextRequest,
  { params }: { params: Promise<{ jobId: string }> }
) {
  try {
    // Check authentication
    const user = await getCurrentUser();
    if (!user) {
      return NextResponse.json(
        { error: "Unauthorized" },
        { status: 401 }
      );
    }

    const { jobId } = await params;

    // Check the job exists and verify authorization
    const existingJob = await prisma.syncJob.findUnique({
      where: { id: jobId },
      select: { createdById: true },
    });

    if (!existingJob) {
      return NextResponse.json(
        { error: "Job not found" },
        { status: 404 }
      );
    }

    // Admins can cancel all jobs; other users can only cancel jobs they created
    if (user.globalRole !== "ADMIN" && existingJob.createdById !== user.id) {
      return NextResponse.json(
        { error: "Forbidden: Admin role required" },
        { status: 403 }
      );
    }

    // Update the job status to CANCELLED, selecting only client-safe fields
    const job = await prisma.syncJob.update({
      where: { id: jobId },
      data: { status: "CANCELLED" },
      select: {
        id: true,
        type: true,
        status: true,
        progress: true,
        progressText: true,
        itemsTotal: true,
        itemsProcessed: true,
        error: true,
        resultData: true,
        createdAt: true,
        startedAt: true,
        completedAt: true,
      },
    });

    // Cancel all sub-jobs in database
    await prisma.syncSubJob.updateMany({
      where: {
        parentJobId: jobId,
        status: { in: ["PENDING", "RUNNING"] }
      },
      data: {
        status: "CANCELLED",
        completedAt: new Date(),
      },
    });

    // Cancel pg-boss jobs via direct SQL
    // group_id in pg-boss is set to the sync job ID
    await prisma.$executeRaw`
      UPDATE pgboss.job
      SET state = 'cancelled'
      WHERE group_id = ${jobId}
      AND state IN ('created', 'active')
    `;

    return NextResponse.json({ success: true, job });
  } catch (error) {
    logger.error("Error cancelling job", error);
    return NextResponse.json(
      { error: "Failed to cancel job" },
      { status: 500 }
    );
  }
}

