import { PgBoss } from "pg-boss";
import { logger } from "@/lib/logger";

const globalForBoss = globalThis as unknown as {
  boss: PgBoss | null | undefined;
};

export async function getBoss(): Promise<PgBoss> {
  if (!globalForBoss.boss) {
    const databaseUrl = process.env.DATABASE_URL;
    if (!databaseUrl) {
      throw new Error("DATABASE_URL environment variable is not set");
    }

    const instance = new PgBoss({
      connectionString: databaseUrl,
      ssl: process.env.NODE_ENV === "production" ? { rejectUnauthorized: false } : undefined,
      schema: process.env.DATABASE_SCHEMA,
    });
    globalForBoss.boss = instance;
    try {
      await instance.start();
    } catch (error) {
      globalForBoss.boss = null;
      throw new Error("Failed to start pg-boss instance", { cause: error });
    }
    logger.log("pg-boss started successfully");
  } else {
    logger.log("pg-boss already initialized; reusing existing instance");
  }
  const boss = globalForBoss.boss;
  if (!boss) {
    throw new Error("pg-boss is not initialized");
  }
  return boss;
}

export async function closeBoss(options?: { timeout?: number }): Promise<void> {
  if (globalForBoss.boss) {
    await globalForBoss.boss.stop({ timeout: options?.timeout ?? 5000 });
    globalForBoss.boss = null;
    logger.log("pg-boss stopped");
  }
}

import { describe, it, expect, vi, beforeEach, afterEach } from "vitest";

// Vitest hoists variables starting with 'mock' before vi.mock() factories run
let mockPgBossInstance: { start: ReturnType<typeof vi.fn>; stop: ReturnType<typeof vi.fn> } | null = null;
const mockPgBossConstructor = vi.fn();

vi.mock("pg-boss", () => {
  mockPgBossConstructor.mockImplementation(function () {
    mockPgBossInstance = {
      start: vi.fn().mockResolvedValue(undefined),
      stop: vi.fn().mockResolvedValue(undefined),
    };
    return mockPgBossInstance;
  });
  return { PgBoss: mockPgBossConstructor };
});

vi.mock("@/lib/logger", () => ({
  logger: {
    log: vi.fn(),
    error: vi.fn(),
    debug: vi.fn(),
    warn: vi.fn(),
  },
}));

describe("getBoss / closeBoss singleton", () => {
  let originalDatabaseUrl: string | undefined;

  beforeEach(() => {
    (globalThis as Record<string, unknown>).boss = null;
    mockPgBossInstance = null;
    originalDatabaseUrl = process.env.DATABASE_URL;
    process.env.DATABASE_URL = "postgres://test:test@localhost:5433/test";
    mockPgBossConstructor.mockClear();
  });

  afterEach(() => {
    (globalThis as Record<string, unknown>).boss = null;
    if (originalDatabaseUrl !== undefined) {
      process.env.DATABASE_URL = originalDatabaseUrl;
    } else {
      delete process.env.DATABASE_URL;
    }
  });

  describe("getBoss", () => {
    it("creates a new PgBoss instance using DATABASE_URL on first call", async () => {
      const { getBoss } = await import("../boss");

      await getBoss();

      expect(mockPgBossConstructor).toHaveBeenCalledWith({
        connectionString: "postgres://test:test@localhost:5433/test",
        ssl: undefined,
        schema: undefined,
      });
      expect(mockPgBossInstance?.start).toHaveBeenCalledOnce();
    });

    it("returns the cached instance without creating a new one on subsequent calls", async () => {
      const { getBoss } = await import("../boss");

      const first = await getBoss();
      const second = await getBoss();

      expect(first).toBe(second);
      expect(mockPgBossConstructor).toHaveBeenCalledOnce();
    });

    it("throws when DATABASE_URL is not set", async () => {
      delete process.env.DATABASE_URL;
      const { getBoss } = await import("../boss");

      await expect(getBoss()).rejects.toThrow(
        "DATABASE_URL environment variable is not set"
      );
      expect(mockPgBossConstructor).not.toHaveBeenCalled();
    });

    it("clears the singleton if start() throws so the next call can retry", async () => {
      const startError = new Error("DB unreachable");
      mockPgBossConstructor.mockImplementationOnce(function () {
        mockPgBossInstance = {
          start: vi.fn().mockRejectedValue(startError),
          stop: vi.fn().mockResolvedValue(undefined),
        };
        return mockPgBossInstance;
      });

      const { getBoss } = await import("../boss");

      await expect(getBoss()).rejects.toThrow("Failed to start pg-boss instance");
      expect((globalThis as Record<string, unknown>).boss).toBeNull();

      // Next call should attempt a fresh start
      await getBoss();
      expect(mockPgBossConstructor).toHaveBeenCalledTimes(2);
    });
  });

  describe("closeBoss", () => {
    it("stops the instance and clears the singleton", async () => {
      const { getBoss, closeBoss } = await import("../boss");

      await getBoss();
      const instance = mockPgBossInstance!;
      await closeBoss();

      expect(instance.stop).toHaveBeenCalledWith({ timeout: 5000 });
      expect((globalThis as Record<string, unknown>).boss).toBeNull();
    });

    it("uses a custom timeout when provided", async () => {
      const { getBoss, closeBoss } = await import("../boss");

      await getBoss();
      const instance = mockPgBossInstance!;
      await closeBoss({ timeout: 1000 });

      expect(instance.stop).toHaveBeenCalledWith({ timeout: 1000 });
    });

    it("is a no-op when no instance exists", async () => {
      const { closeBoss } = await import("../boss");

      await expect(closeBoss()).resolves.toBeUndefined();
      expect(mockPgBossConstructor).not.toHaveBeenCalled();
    });

    it("allows getBoss to create a fresh instance after close", async () => {
      const { getBoss, closeBoss } = await import("../boss");

      const first = await getBoss();
      await closeBoss();
      const second = await getBoss();

      expect(first).not.toBe(second);
      expect(mockPgBossConstructor).toHaveBeenCalledTimes(2);
    });
  });
});

